// pmaMediaPrefix keeps the media surface fetches inside /media (INV4's
// negative guard below asserts the flow lines never do).
const pmaMediaPrefix = "/media/"

// pmaLog is the slog capture (the cmd/mellifera decision_log_test pattern):
// the default logger swaps to a text handler over this locked buffer for the
// whole joint (production logs through slog's DEFAULT logger — there is no
// other seam). Windows are byte marks taken between sequential actions.
type pmaLog struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (l *pmaLog) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.buf.Write(p)
}

func (l *pmaLog) mark() int {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.buf.Len()
}

// since returns the lines logged after the given mark (nil when nothing was).
func (l *pmaLog) since(mark int) []string {
	l.mu.Lock()
	defer l.mu.Unlock()
	s := strings.TrimRight(l.buf.String()[mark:], "\n")
	if s == "" {
		return nil
	}
	return strings.Split(s, "\n")
}

// pmaFlowLines filters a window to the lines of one flow message (the text
// handler renders `msg="…"` with quoting).
func pmaFlowLines(window []string, msg string) []string {
	var out []string
	for _, ln := range window {
		if strings.Contains(ln, `msg="`+msg+`"`) {
			out = append(out, ln)
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// Mirrors of the package-main thin shells (the composition root's wiring).

// pmaGateCodecs mirrors cmd/mellifera's packGateCodecs (pack-manifest-audio
// D7): the stored ffprobe facts rendered as `codec profile` for the video,
// then the audio codecs with multiplicity — `h264 High, aac`, `hevc Main 10,
// aac LC ×2`, `none` when nothing renders. Pure.
func pmaGateCodecs(ff map[string]any) string {
	streams, _ := ff["streams"].([]any)
	var video map[string]any
	var audio []map[string]any
	for _, s := range streams {
		m, ok := s.(map[string]any)
		if !ok {
			continue
		}
		switch m["codec_type"] {
		case "video":
			if video == nil {
				video = m
			}
		case "audio":
			audio = append(audio, m)
		}
	}
	render := func(s map[string]any) string {
		if s == nil {
			return ""
		}
		name, _ := s["codec_name"].(string)
		name = strings.ToLower(strings.TrimSpace(name))
		profile, _ := s["profile"].(string)
		profile = strings.TrimSpace(profile)
		switch {
		case name == "" && profile == "":
			return ""
		case profile == "":
			return name
		case name == "":
			return profile
		default:
			return name + " " + profile
		}
	}
	var parts []string
	if r := render(video); r != "" {
		parts = append(parts, r)
	}
	counts := map[string]int{}
	var order []string
	for _, a := range audio {
		r := render(a)
		if r == "" {
			continue
		}
		if counts[r] == 0 {
			order = append(order, r)
		}
		counts[r]++
	}
	for _, r := range order {
		if n := counts[r]; n > 1 {
			parts = append(parts, fmt.Sprintf("%s ×%d", r, n))
		} else {
			parts = append(parts, r)
		}
	}
	if len(parts) == 0 {
		return "none"
	}
	return strings.Join(parts, ", ")
}

// pmaGateLine mirrors cmd/mellifera's logPackGate (D7): ONE "pack: gate" INFO
// line per pack job — item, class (Classify with the knob out of the way),
// gate (open | the refusal token), codecs (the compact fact rendering).
func pmaGateLine(itemID string, ff map[string]any, gate stream.Gate) {
	verdict := "open"
	if gate != stream.GateOpen {
		verdict = string(gate)
	}
	slog.Info("pack: gate", "item", itemID, "class", string(stream.Classify(ff, true)),
		"gate", verdict, "codecs", pmaGateCodecs(ff))
}

// pmaDecisionReason mirrors cmd/mellifera's playbackDecisionReason (D8).
func pmaDecisionReason(mode, state, stateReason string, coolUntil, now time.Time) string {
	switch {
	case mode == stream.ModeHls:
		return "packaged"
	case coolUntil.After(now):
		return "cooldown"
	case state == stream.StateFailed:
		return "failed"
	case stateReason != "":
		return stateReason
	default:
		return "unpackaged"
	}
}

// pmaLogDecision mirrors cmd/mellifera's logPlaybackDecision (D7): the ONE
// descriptor line with the codecs source named — never a token, never a play
// URL, never the codec strings.
func pmaLogDecision(itemID, mode, state, reason, codecsSrc string) {
	slog.Info("playback: descriptor", "item", itemID, "mode", mode, "state", state, "reason", reason, "codecs_src", codecsSrc)
}

// pmaCooldowns mirrors cmd/mellifera's streamCooldowns (the ledger rows under
// the streams lane into item → cooldown deadline).
func pmaCooldowns(ctx context.Context, st *store.Store) map[string]time.Time {
	cool := map[string]time.Time{}
	rows, err := st.ListFailures(ctx)
	if err != nil {
		return cool
	}
	for _, r := range rows {
		if r.PluginID == pbStreamsLane {
			cool[r.ItemID] = r.NextEligibleAt
		}
	}
	return cool
}

// pmaPlaybackGET mirrors cmd/mellifera's playbackDescriptor (D-7/D7): pure
// delegation over Describe + a fresh token, then the ONE decision line.
func pmaPlaybackGET(ctx context.Context, st *store.Store, media *stream.Service, itemID string) (api.Playback, error) {
	row, err := st.GetItem(ctx, itemID)
	if err != nil {
		return api.Playback{}, err
	}
	var doc map[string]any
	if err := json.Unmarshal(row.Document, &doc); err != nil {
		return api.Playback{}, err
	}
	mode, state, playURL, sections, voiceovers, stateReason, codecs, codecsSrc, _ := media.Describe(itemID, doc)
	token, _ := media.Issue(itemID, time.Now())
	pmaLogDecision(itemID, mode, state,
		pmaDecisionReason(mode, state, stateReason, pmaCooldowns(ctx, st)[itemID], time.Now()), codecsSrc)
	return api.Playback{
		Mode: mode, State: state, PlayURL: playURL, StateReason: stateReason,
		Codecs: codecs, Sections: sections, Voiceovers: voiceovers, Token: token,
	}, nil
}

// pmaMasterVersion mirrors cmd/mellifera's masterRuleVersion (fix-tv-unblock-2
// Interfaces 2): boolean `true` is the legacy v1 write, a JSON number its
// integer version (JSON decoding shapes namespace numbers as float64 — a raw
// int type-assert would read every version as 0), anything else or absent 0.
func pmaMasterVersion(streams map[string]any) int {
	switch v := streams["master"].(type) {
	case bool:
		if v {
			return 1
		}
	case float64:
		return int(v)
	}
	return 0
}

// pmaLegacyRepack mirrors cmd/mellifera's legacyRepackOnPlay (pack-manifest-
// audio D5, re-versioned by fix-tv-unblock-2 Interfaces 2): a complete
// namespace with a nonce whose pack-lane RULE VERSION is older than
// pack.MasterRuleVersion is a stale build — the play enqueues exactly ONE
// repack; gate-closed skips with ONE INFO line; the decision reads ONLY the
// stored namespace doc.
func pmaLegacyRepack(enqueue func(string) error, doc map[string]any, itemID string, optInCodecs bool) (queued, handled bool) {
	streams, _ := doc["streams"].(map[string]any)
	state, _ := streams["state"].(string)
	nonce, _ := streams["nonce"].(string)
	if state != stream.StateComplete || nonce == "" || pmaMasterVersion(streams) >= pack.MasterRuleVersion {
		return false, false
	}
	ff, _ := doc["ffprobe"].(map[string]any)
	if gate := stream.PackGate(ff, optInCodecs); gate != stream.GateOpen {
		slog.Info("orchestrator: legacy repack skipped", "item", itemID, "reason", string(gate))
		return false, true
	}
	if err := enqueue(itemID); err != nil {
		slog.Warn("orchestrator: legacy repack enqueue deferred", "item", itemID, "error", err)
		return false, true
	}
	slog.Info("orchestrator: legacy repack queued", "item", itemID)
	return true, true
}

// pmaPackOnPlay mirrors cmd/mellifera's packOnPlay (D-8): the legacy-repack
// decision first, then the ordinary OnPlay policy over the item's projection.
func pmaPackOnPlay(ctx context.Context, st *store.Store, enqueue func(string) error, row store.Item, optInCodecs bool) (bool, error) {
	doc := map[string]any{}
	_ = json.Unmarshal(row.Document, &doc)
	if queued, handled := pmaLegacyRepack(enqueue, doc, row.ID, optInCodecs); handled {
		return queued, nil
	}
	streams, _ := doc["streams"].(map[string]any)
	state, _ := streams["state"].(string)
	ff, _ := doc["ffprobe"].(map[string]any)
	ep := orchestrator.Episode{
		ItemID:    row.ID,
		Packable:  stream.PackGate(ff, optInCodecs) == stream.GateOpen,
		Packaged:  state == stream.StatePartial || state == stream.StateComplete,
		CoolUntil: pmaCooldowns(ctx, st)[row.ID],
	}
	if !orchestrator.OnPlay(ep, time.Now()) {
		return false, nil
	}
	if err := enqueue(row.ID); err != nil {
		slog.Warn("orchestrator: pack-on-play enqueue deferred", "item", row.ID, "error", err)
		return false, nil
	}
	slog.Info("orchestrator: pack-on-play", "item", row.ID)
	return true, nil
}

// pmaRetryFailed mirrors cmd/mellifera's retryFailedPack (the play verb's
// retry branch) — kept for closure fidelity; no leg drives it.
func pmaRetryFailed(ctx context.Context, st *store.Store, enqueue func(string) error, row store.Item, optInCodecs bool) (bool, error) {
	doc := map[string]any{}
	_ = json.Unmarshal(row.Document, &doc)
	streams, _ := doc["streams"].(map[string]any)
	if state, _ := streams["state"].(string); state != stream.StateFailed {
		return false, nil
	}
	ff, _ := doc["ffprobe"].(map[string]any)
	if gate := stream.PackGate(ff, optInCodecs); gate != stream.GateOpen {
		return false, refusal.PlayRefusal{Reason: string(gate)}
	}
	if err := enqueue(row.ID); err != nil {
		return false, err
	}
	return true, nil
}

// ---------------------------------------------------------------------------
// The joint's world: queue + router over the pbNewWorld composition.

// pmaQueue starts one enrich queue over the world with the production
// PackItem wiring (main.go's closure in miniature: the D7 gate line, the
// PackGate pre-check as refusal.PolicyRefusal, the real pack, the Codecs
// outcome). extra runs inside the closure before Pack (the tail-gate legs'
// call counter).
func pmaQueue(t *testing.T, w *pbWorld, media *stream.Service, extra func()) *enrich.Queue {
	t.Helper()
	deps := enrich.Deps{Store: w.st, Modules: w.reg, Plugins: w.mgr}
	deps.PackItem = func(ctx context.Context, itemID, absPath string, ffprobe map[string]any, voiceovers []string) (pack.PackOutcome, error) {
		pmaGateLine(itemID, ffprobe, stream.PackGate(ffprobe, media.OptInCodecs))
		if gate := stream.PackGate(ffprobe, media.OptInCodecs); gate != stream.GateOpen {
			return pack.PackOutcome{}, refusal.PolicyRefusal{Reason: string(gate)}
		}
		if extra != nil {
			extra()
		}
		build, err := media.Pack(ctx, itemID, absPath, ffprobe, voiceovers)
		return pack.PackOutcome{Playlist: build.Playlist, Nonce: build.Nonce, Codecs: build.Codecs, Layout: build.Layout}, err
	}
	q := enrich.NewQueue(deps, enrich.QueueConfig{Workers: 2, Backoff: time.Millisecond})
	if err := q.Start(context.Background()); err != nil {
		t.Fatalf("queue Start: %v", err)
	}
	t.Cleanup(q.Stop)
	return q
}

// pmaServer boots a real api+web router over the world with the mirrored
// descriptor and play closures (decision lines included). enqueue is the play
// verb's EnqueuePack seam.
func pmaServer(t *testing.T, w *pbWorld, enqueue func(string) error) string {
	t.Helper()
	apiH := api.New(api.Deps{
		AdminToken: w.token,
		Store:      w.st,
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			return pmaPlaybackGET(ctx, w.st, w.media, itemID)
		},
		Play: func(ctx context.Context, itemID string, retry bool, _ *float64) (bool, error) {
			row, err := w.st.GetItem(ctx, itemID)
			if err != nil {
				return false, err // sql.ErrNoRows → 404 at the handler
			}
			if !retry {
				return pmaPackOnPlay(ctx, w.st, enqueue, row, w.media.OptInCodecs)
			}
			return pmaRetryFailed(ctx, w.st, enqueue, row, w.media.OptInCodecs)
		},
	})
	srv := httptest.NewServer(web.Handler(apiH, web.Options{Media: w.media}))
	t.Cleanup(srv.Close)
	return srv.URL
}

// pmaSeedItem puts one item row straight through the store (the gateSeedItem
// pattern — the lane's seams read stored facts only): a real fixture file at
// parsed.absolute_path, the given ffprobe facts, an optional audio sidecar
// fact (the lane's documentVoiceoverPaths derivation turns it into the
// rendition build's voiceover input), and the given streams namespace.
// sidecarRel is relative to the fixture's own directory.
func pmaSeedItem(t *testing.T, w *pbWorld, libID int64, id, rel, absPath string, ff map[string]any, sidecarRel string, streams map[string]any) {
	t.Helper()
	parsed := map[string]any{"absolute_path": absPath}
	if sidecarRel != "" {
		parsed["sidecars"] = []any{map[string]any{
			"kind": "audio", "relative_path": sidecarRel,
		}}
	}
	doc := map[string]any{"parsed": parsed, "ffprobe": ff, "streams": streams}
	raw, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal doc for %s: %v", id, err)
	}
	err = w.st.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "serial", LibraryID: libID, FileID: id,
		RelativePath: rel, MediaType: "movie", Document: raw, SchemaVersion: 1,
	})
	if err != nil {
		t.Fatalf("seed item %s: %v", id, err)
	}
}

// pmaH264Facts is the canonical pack-class fact shape (h264 High + profile-
// less aac in a Matroska container — pack_gate_log_test's h264Facts, whose
// compact rendering is `h264 High, aac`; 5 s, past the harness's 2 s head
// chunk, so both pack phases run).
func pmaH264Facts() map[string]any {
	return map[string]any{
		"format": map[string]any{"format_name": "matroska,webm", "duration": "5.000000"},
		"streams": []any{
			map[string]any{"codec_type": "video", "codec_name": "h264", "profile": "High"},
			map[string]any{"codec_type": "audio", "codec_name": "aac"},
		},
	}
}

