// pmaMakeSidecar generates a real AAC sidecar audio file (the voiceover
// fixture — the pack lane's rendition input).
func pmaMakeSidecar(t *testing.T, path string) {
	t.Helper()
	out, err := exec.Command("ffmpeg", "-nostdin", "-y",
		"-f", "lavfi", "-i", "sine=frequency=600:sample_rate=44100:duration=5",
		"-c:a", "aac", "-f", "ipod", path).CombinedOutput()
	if err != nil {
		t.Fatalf("ffmpeg sidecar %s: %v: %s", filepath.Base(path), err, out)
	}
}

// pmaTailGate is the hermetic head-first window (the six-slot's "drive the
// afterHead hook or a small-enough head window" — afterHead is unexported, so
// the joint gates the tail phase instead): the pack service's FFmpeg points at
// a wrapper script that passes the head invocation through and BLOCKS the tail
// invocation (its args carry -ss) until released. The partial build's rename
// happens BEFORE packTail starts, so the started marker fires exactly when the
// partial build is published — deterministic, nothing polls in the test.
type pmaTailGate struct {
	started  chan struct{}
	startedP string
	releaseP string
	once     sync.Once
}

// pmaNewTailGate writes the wrapper script (realFFmpeg is the exec'd real
// binary) and starts the marker watcher. Release is idempotent and
// cleanup-guarded (a failed leg never leaves a blocked ffmpeg behind).
func pmaNewTailGate(t *testing.T, dir, realFFmpeg string) *pmaTailGate {
	t.Helper()
	g := &pmaTailGate{
		started:  make(chan struct{}),
		startedP: filepath.Join(dir, "tail-started"),
		releaseP: filepath.Join(dir, "release"),
	}
	script := filepath.Join(dir, "ffmpeg-block-tail.sh")
	body := "#!/bin/sh\n" +
		"for a in \"$@\"; do\n" +
		"  if [ \"$a\" = \"-ss\" ]; then\n" +
		"    touch '" + g.startedP + "'\n" +
		"    while [ ! -f '" + g.releaseP + "' ]; do sleep 0.02; done\n" +
		"    break\n" +
		"  fi\n" +
		"done\n" +
		"exec '" + realFFmpeg + "' \"$@\"\n"
	if err := os.WriteFile(script, []byte(body), 0o755); err != nil {
		t.Fatalf("write tail-gate wrapper: %v", err)
	}
	go func() {
		deadline := time.Now().Add(5 * time.Minute)
		for time.Now().Before(deadline) {
			if _, err := os.Stat(g.startedP); err == nil {
				select {
				case <-g.started:
				default:
					close(g.started)
				}
				return
			}
			if _, err := os.Stat(g.releaseP); err == nil {
				return // released before the tail ever ran; nothing to signal
			}
			time.Sleep(2 * time.Millisecond)
		}
	}()
	t.Cleanup(g.release)
	return g
}

func (g *pmaTailGate) release() {
	g.once.Do(func() { _ = os.WriteFile(g.releaseP, []byte("go"), 0o644) })
}

// pmaBlockedService builds a stream service sharing the world's root and
// secret but running ffmpeg through the tail gate (pack-manifest-audio D2's
// head-first publish observed mid-run from OUTSIDE the lane).
func pmaBlockedService(w *pbWorld, ffmpegBin string) *stream.Service {
	return &stream.Service{
		Root:        w.media.Root,
		Secret:      w.media.Secret,
		HeadChunk:   2 * time.Second,
		SegmentTime: 1 * time.Second,
		PackTimeout: 60 * time.Second,
		FFmpeg:      ffmpegBin,
		OptInCodecs: w.media.OptInCodecs,
		Original:    w.media.Original,
	}
}

// pmaHandLegacyBuild lays one valid LEGACY flat-root build (pack-manifest-audio
// D5's coexistence shape: the media playlist, init, and segments at the build
// root — the pre-master layout) under root/<itemID>/<nonce>. It validates
// (ValidateBuild's walk: one playlist, every ref inside the build, complete
// coverage) and serves (the surface answers any published artifact path).
func pmaHandLegacyBuild(t *testing.T, root, itemID, nonce string) string {
	t.Helper()
	dir := filepath.Join(root, itemID, nonce)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("mkdir legacy build: %v", err)
	}
	pl := "#EXTM3U\n" +
		"#EXT-X-VERSION:7\n" +
		"#EXT-X-TARGETDURATION:4\n" +
		`#EXT-X-MAP:URI="init.mp4"` + "\n" +
		"#EXTINF:4.0,\nseg-00000.m4s\n" +
		"#EXTINF:4.0,\nseg-00001.m4s\n" +
		"#EXT-X-ENDLIST\n"
	for name, body := range map[string]string{
		"index.m3u8":    pl,
		"init.mp4":      "legacy-init-bytes",
		"seg-00000.m4s": "legacy-seg-0-bytes",
		"seg-00001.m4s": "legacy-seg-1-bytes",
	} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
			t.Fatalf("write legacy artifact %s: %v", name, err)
		}
	}
	return dir
}

// ---------------------------------------------------------------------------
// Master playlist parsing (the served text is the contract).

// pmaMasterView is one fetched master's line classes: the EXT-X-STREAM-INF
// attribute lines, the EXT-X-MEDIA lines, and the plain URI lines (the variant
// playlist references — the only URI lines a correct master carries).
type pmaMasterView struct {
	streamInf []string
	media     []string
	uris      []string
}

func pmaParseMaster(body string) pmaMasterView {
	var v pmaMasterView
	for _, raw := range strings.Split(body, "\n") {
		l := strings.TrimSpace(raw)
		switch {
		case l == "":
		case strings.HasPrefix(l, "#EXT-X-STREAM-INF:"):
			v.streamInf = append(v.streamInf, l)
		case strings.HasPrefix(l, "#EXT-X-MEDIA:"):
			v.media = append(v.media, l)
		case strings.HasPrefix(l, "#"):
		default:
			v.uris = append(v.uris, l)
		}
	}
	return v
}

// pmaAttr reads one attribute's value off an HLS tag line (quoted first, then
// the bare next-comma form the unquoted attributes use).
func pmaAttr(line, key string) string {
	if i := strings.Index(line, key+`="`); i >= 0 {
		rest := line[i+len(key)+2:]
		if j := strings.Index(rest, `"`); j >= 0 {
			return rest[:j]
		}
	}
	if i := strings.Index(line, key+"="); i >= 0 {
		rest := line[i+len(key)+1:]
		if j := strings.Index(rest, ","); j >= 0 {
			return rest[:j]
		}
		return rest
	}
	return ""
}

// pmaGetMedia fetches one /media path with a fresh token (any stale query on
// the path is stripped first: the serve layer embeds the REQUEST's token into
// the served playlist, so the assertion token must be the only one) and fails
// on any non-200.
func pmaGetMedia(t *testing.T, w *pbWorld, path, token string) []byte {
	t.Helper()
	status, body, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+stripToken(path)+"?token="+token, "", nil)
	if status != http.StatusOK {
		t.Fatalf("media GET %s: status %d, want 200 (body=%s)", stripToken(path), status, body)
	}
	return body
}

// pmaNonceDirs lists the build-nonce directories under one item's artifact
// root (lane scratch dirs are prefixed .tmp-: ".tmp-<nonce>" and
// ".tmp-tail-<nonce>").
func pmaNonceDirs(t *testing.T, root, itemID string) []string {
	t.Helper()
	entries, err := os.ReadDir(filepath.Join(root, itemID))
	if err != nil {
		t.Fatalf("read artifact dir %s: %v", itemID, err)
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() && !strings.HasPrefix(e.Name(), ".tmp-") {
			out = append(out, e.Name())
		}
	}
	return out
}

// pmaAwaitFreshNonce polls the store until the item's streams namespace is
// republished PAST the given old nonce at state complete (the lazy-repack
// observable — the namespace was already complete under the old nonce, so a
// state poll would return the stale document).
func pmaAwaitFreshNonce(t *testing.T, st *store.Store, itemID, oldNonce string, timeout time.Duration) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		it, err := st.GetItem(context.Background(), itemID)
		if err == nil {
			var doc map[string]any
			_ = json.Unmarshal(it.Document, &doc)
			if s, ok := doc["streams"].(map[string]any); ok && s["state"] == stream.StateComplete {
				if n, _ := s["nonce"].(string); n != "" && n != oldNonce {
					return s
				}
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("item %s streams never republished past nonce %q (timeout %v)", itemID, oldNonce, timeout)
	return nil
}

// pmaDescriptor fetches the descriptor through the real router and decodes
// the served bytes (state_reason and codecs stay raw — the wire is the
// contract, a typed nil would accept a JSON null).
func pmaDescriptor(t *testing.T, baseURL string, w *pbWorld, itemID string) gateDescriptor {
	t.Helper()
	status, body, _ := pbDo(t, w.client, http.MethodGet, baseURL+"/api/v1/items/"+itemID+"/playback", w.token, nil)
	if status != http.StatusOK {
		t.Fatalf("descriptor %s: status %d, want 200 (body=%s)", itemID, status, body)
	}
	var d gateDescriptor
	if err := json.Unmarshal(body, &d); err != nil {
		t.Fatalf("decode descriptor %s: %v (body=%s)", itemID, err, body)
	}
	return d
}

// pmaCodecsWire decodes the descriptor's raw codecs JSON into strings.
func pmaCodecsWire(t *testing.T, raw json.RawMessage) []string {
	t.Helper()
	var out []string
	if err := json.Unmarshal(raw, &out); err != nil || len(out) == 0 {
		t.Fatalf("descriptor codecs wire = %s (decode %v), want a non-empty array", raw, err)
	}
	return out
}

// ---------------------------------------------------------------------------
// The joint.

func TestPackManifestAudioJoint(t *testing.T) {
	w := pbNewWorld(t)
	// The knob rides ON for this joint: leg (c)'s pack runs through the gate
	// over the Matroska HEVC facts, which only the opt-in knob admits. The
	// h264 legs are open under either position; every closure reads the same
	// knob the world serves.
	w.media.OptInCodecs = true

	// The slog capture (decision_log_test pattern): the default logger IS the
	// production seam. Never parallel.
	log := &pmaLog{}
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(log, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	// One library owns the seeded items (real store rows, no scan — the
	// scanner's stamping is not these legs' subject).
	libRoot := t.TempDir()
	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA Pack Manifest Audio")

	// The real ffmpeg binary the tail gates wrap.
	realFFmpeg, err := exec.LookPath("ffmpeg")
	if err != nil {
		t.Skipf("ffmpeg required: %v", err)
	}

	// --- fixtures -----------------------------------------------------------
	fixtures := t.TempDir()
	mkvA := filepath.Join(fixtures, "Movie A.mkv")
	pbMakeMKV(t, mkvA, 5*time.Second, false)
	sidecarA := filepath.Join(fixtures, "vo-a.m4a")
	pmaMakeSidecar(t, sidecarA)
	mkvB := filepath.Join(fixtures, "Movie B.mkv")
	pbMakeMKV(t, mkvB, 5*time.Second, false)
	mkvC := filepath.Join(fixtures, "Movie C.mkv")
	pbMakeMKV(t, mkvC, 5*time.Second, false)
	mkvE := filepath.Join(fixtures, "Movie E.mkv")
	pbMakeMKV(t, mkvE, 5*time.Second, false)

	// The plain production queue (legs a, c, d ride it) and the router.
	qMain := pmaQueue(t, w, w.media, nil)
	enqueueMain := w.pbEnqueue(qMain)
	baseURL := pmaServer(t, w, enqueueMain)

	// Seed the rendition item (legs a/d): MKV + a real audio sidecar fact.
	pmaSeedItem(t, w, libID, "pma_a", "Movie A.mkv", mkvA, pmaH264Facts(), "vo-a.m4a",
		map[string]any{"state": stream.StateNone})

	// --- LEG (a): the rendition pack's served master -------------------------
	// (leg (d) asserts over this same job's captured log window, below)
	var flowWindow []string
	t.Run("a_rendition_master", func(t *testing.T) {
		mark := log.mark()
		if err := enqueueMain("pma_a"); err != nil {
			t.Fatalf("enqueue pma_a: %v", err)
		}
		streams := pbAwaitStreams(t, w.st, "pma_a", "complete", 60*time.Second)
		pbAwaitIdle(t, qMain, 30*time.Second)
		flowWindow = log.since(mark)
		nonce, _ := streams["nonce"].(string)
		if nonce == "" {
			t.Fatalf("persisted streams missing nonce: %v", streams)
		}

		// The descriptor answers hls with the recorded codecs (video first,
		// then the deduped audio) — and its decision line names the source.
		dMark := log.mark()
		d := pmaDescriptor(t, baseURL, w, "pma_a")
		if d.Mode != "hls" || d.State != "complete" {
			t.Fatalf("pma_a descriptor = mode %q state %q, want hls/complete", d.Mode, d.State)
		}
		if !strings.HasPrefix(d.PlayURL, pmaMediaPrefix+"pma_a/"+nonce+"/index.m3u8?token=") {
			t.Fatalf("play URL = %q, want the persisted nonce's master playlist with a token", d.PlayURL)
		}
		served := pmaCodecsWire(t, d.Codecs)
		if len(served) != 2 || !strings.HasPrefix(served[0], "avc1.") || served[1] != "mp4a.40.2" {
			t.Fatalf("descriptor codecs = %v, want [avc1.*, mp4a.40.2] (video first, deduped audio)", served)
		}
		for _, ln := range pmaFlowLines(log.since(dMark), "playback: descriptor") {
			if !strings.Contains(ln, "codecs_src=recorded") {
				t.Fatalf("fresh pack's decision line names no recorded source: %s", ln)
			}
		}

		// The SERVED master is the contract: fetch through the media surface.
		token, _ := w.media.Issue("pma_a", time.Now())
		master := pmaGetMedia(t, w, d.PlayURL, token)
		v := pmaParseMaster(string(master))
		if len(v.streamInf) != 1 {
			t.Fatalf("master carries %d EXT-X-STREAM-INF variants, want exactly ONE:\n%s", len(v.streamInf), master)
		}
		if len(v.uris) != 1 {
			t.Fatalf("master carries %d URI lines, want exactly ONE (no audio rendition appears as a variant):\n%s", len(v.uris), master)
		}
		vi := v.streamInf[0]
		if got := pmaAttr(vi, "CODECS"); !strings.HasPrefix(got, "avc1.") || strings.Contains(got, "mp4a") {
			t.Fatalf("variant line CODECS = %q, want the video-only composition avc1.* (audio rides EXT-X-MEDIA only)", got)
		}
		if pmaAttr(vi, "AUDIO") != "aud" {
			t.Fatalf("variant line AUDIO = %q, want the aud group", pmaAttr(vi, "AUDIO"))
		}
		if pmaAttr(vi, "RESOLUTION") != "128x72" {
			t.Fatalf("variant line RESOLUTION = %q, want the probed 128x72", pmaAttr(vi, "RESOLUTION"))
		}
		if !strings.Contains(vi, "BANDWIDTH=") {
			t.Fatalf("variant line carries no BANDWIDTH: %s", vi)
		}
		if len(v.media) != 2 {
			t.Fatalf("master carries %d EXT-X-MEDIA renditions, want 2 (embedded + sidecar):\n%s", len(v.media), master)
		}
		if strings.Count(string(master), "DEFAULT=YES") != 1 {
			t.Fatalf("master carries %d DEFAULT=YES, want exactly ONE (the embedded audio):\n%s",
				strings.Count(string(master), "DEFAULT=YES"), master)
		}
		embedded, voiceover := v.media[0], v.media[1]
		if pmaAttr(embedded, "NAME") != "Audio 1" || pmaAttr(voiceover, "NAME") != "Audio 2" {
			t.Fatalf("EXT-X-MEDIA NAMEs = %q / %q, want the stable Audio K ordinals (no language facts in the fixtures)",
				pmaAttr(embedded, "NAME"), pmaAttr(voiceover, "NAME"))
		}
		if pmaAttr(embedded, "TYPE") != "AUDIO" || pmaAttr(embedded, "GROUP-ID") != "aud" ||
			pmaAttr(embedded, "DEFAULT") != "YES" || pmaAttr(embedded, "AUTOSELECT") != "YES" {
			t.Fatalf("embedded rendition line = %s, want TYPE=AUDIO GROUP-ID=aud DEFAULT=YES AUTOSELECT=YES", embedded)
		}
		if pmaAttr(voiceover, "DEFAULT") != "NO" || pmaAttr(voiceover, "AUTOSELECT") != "YES" {
			t.Fatalf("voiceover rendition line = %s, want DEFAULT=NO AUTOSELECT=YES (selectable, never default)", voiceover)
		}
		if pmaAttr(embedded, "URI") != "rend1/index.m3u8?token="+token || pmaAttr(voiceover, "URI") != "rend2/index.m3u8?token="+token {
			t.Fatalf("EXT-X-MEDIA URIs = %q / %q, want the tokenized rend1/rend2 playlists (self-authorizing bytes)",
				pmaAttr(embedded, "URI"), pmaAttr(voiceover, "URI"))
		}
		if pmaAttr(embedded, "CODECS") != "mp4a.40.2" {
			t.Fatalf("embedded rendition CODECS = %q, want mp4a.40.2 (carry-when-composed)", pmaAttr(embedded, "CODECS"))
		}
		if !strings.Contains(v.uris[0], "rend0/index.m3u8?token="+token) {
			t.Fatalf("master URI line = %q, want the tokenized rend0 variant playlist", v.uris[0])
		}
		if strings.Contains(string(master), "LANGUAGE=") {
			t.Fatalf("master carries LANGUAGE with no language facts anywhere:\n%s", master)
		}
		// The audio renditions SERVE: the master's group members resolve.
		for _, uri := range []string{pmaAttr(embedded, "URI"), pmaAttr(voiceover, "URI")} {
			pl := pmaGetMedia(t, w, pbPlaylistURI(d.PlayURL, uri), token)
			if !strings.Contains(string(pl), "#EXTM3U") {
				t.Fatalf("audio rendition %s served no playlist:\n%s", uri, pl)
			}
		}
		// The variant playlist is the complete merged build.
		_, _, vBody := pbVariantPlaylist(t, w.client, baseURL, d.PlayURL)
		playlist := string(vBody)
		if !strings.Contains(playlist, "#EXT-X-ENDLIST") || !strings.Contains(playlist, "#EXT-X-DISCONTINUITY") || !strings.Contains(playlist, "t/") {
			t.Fatalf("rend0 variant playlist missing the two-phase complete markers:\n%s", playlist)
		}
	})

	// --- LEG (d): the pack flow lines over leg (a)'s real job ----------------
	t.Run("d_pack_flow_lines", func(t *testing.T) {
		gate := pmaFlowLines(flowWindow, "pack: gate")
		published := pmaFlowLines(flowWindow, "streams: pack published")
		if len(gate) != 1 {
			t.Fatalf("captured %d pack: gate lines for pma_a, want exactly ONE:\n%s",
				len(gate), strings.Join(flowWindow, "\n"))
		}
		if len(published) != 1 {
			t.Fatalf("captured %d published lines for pma_a, want exactly ONE:\n%s",
				len(published), strings.Join(flowWindow, "\n"))
		}
		gateIdx, pubIdx := -1, -1
		for i, ln := range flowWindow {
			if strings.Contains(ln, `msg="pack: gate"`) {
				gateIdx = i
			}
			if strings.Contains(ln, `msg="streams: pack published"`) {
				pubIdx = i
			}
		}
		if gateIdx < 0 || pubIdx < 0 || gateIdx > pubIdx {
			t.Fatalf("flow order broken: gate at %d, publish at %d in:\n%s",
				gateIdx, pubIdx, strings.Join(flowWindow, "\n"))
		}
		nonce, _ := gateStreams(t, w, "pma_a")["nonce"].(string)
		for _, field := range []string{
			"item=pma_a", "class=pack", "gate=open", `codecs="h264 High, aac"`,
		} {
			if !strings.Contains(gate[0], field) {
				t.Fatalf("gate line %q lacks %q", gate[0], field)
			}
		}
		for _, field := range []string{
			"item=pma_a", "nonce=" + nonce, "layout=rendition", "variants=3",
			"audio=2", "codecs=recorded", "probes=3",
		} {
			if !strings.Contains(published[0], field) {
				t.Fatalf("published line %q lacks %q", published[0], field)
			}
		}
		// ONE line per moment: no per-segment chatter anywhere in the window.
		joined := strings.Join(flowWindow, "\n")
		if strings.Contains(joined, "seg-") {
			t.Fatalf("pack flow logged per-segment lines:\n%s", joined)
		}
		// INV4: no token material and no play URL anywhere in the flow.
		if strings.Contains(joined, "token=") || strings.Contains(joined, pmaMediaPrefix) {
			t.Fatalf("pack flow log carries token or play-URL material (INV4):\n%s", joined)
		}
	})

	// --- LEG (b): the single-variant master, partial and complete ------------
	t.Run("b_single_variant_master", func(t *testing.T) {
		gateDir := t.TempDir()
		gate := pmaNewTailGate(t, gateDir, realFFmpeg)
		blocked := pmaBlockedService(w, filepath.Join(gateDir, "ffmpeg-block-tail.sh"))
		qB := pmaQueue(t, w, blocked, nil)
		enqueueB := w.pbEnqueue(qB)
		// The descriptor rides the FIRST server (its Describe/serve reads the
		// shared root; the blocked service only gates PACKING).
		pmaSeedItem(t, w, libID, "pma_b", "Movie B.mkv", mkvB, pmaH264Facts(), "",
			map[string]any{"state": stream.StateNone})

		mark := log.mark()
		if err := enqueueB("pma_b"); err != nil {
			t.Fatalf("enqueue pma_b: %v", err)
		}
		select {
		case <-gate.started: // the rename happened: the PARTIAL build is live
		case <-time.After(60 * time.Second):
			gate.release()
			t.Fatalf("the head-first publish never fired the tail gate; log:\n%s",
				strings.Join(log.since(mark), "\n"))
		}

		// The partial build's nonce: exactly one published dir exists (the
		// rename precedes the blocked tail; scratch dirs are .tmp- prefixed).
		dirs := pmaNonceDirs(t, w.media.Root, "pma_b")
		if len(dirs) != 1 {
			gate.release()
			t.Fatalf("partial build nonce dirs = %v, want exactly one", dirs)
		}
		nonce := dirs[0]
		token, _ := w.media.Issue("pma_b", time.Now())
		vStatus, partialMaster, _ := pbDo(t, w.client, http.MethodGet,
			w.baseURL+pmaMediaPrefix+"pma_b/"+nonce+"/index.m3u8?token="+token, "", nil)
		if vStatus != http.StatusOK {
			gate.release()
			t.Fatalf("partial master: status %d, want 200", vStatus)
		}
		pv := pmaParseMaster(string(partialMaster))
		if len(pv.streamInf) != 1 || len(pv.uris) != 1 || len(pv.media) != 0 {
			gate.release()
			t.Fatalf("partial build root = %+v, want the single-variant master shape (one variant, no EXT-X-MEDIA):\n%s",
				pv, partialMaster)
		}
		vi := pv.streamInf[0]
		if got := pmaAttr(vi, "CODECS"); !strings.HasPrefix(got, "avc1.") || !strings.Contains(got, "mp4a.40.2") {
			gate.release()
			t.Fatalf("single-variant CODECS = %q, want the muxed video+audio composition", got)
		}
		if pmaAttr(vi, "AUDIO") != "" {
			gate.release()
			t.Fatalf("single-variant master declares an AUDIO group %q — the muxed variant carries no group", pmaAttr(vi, "AUDIO"))
		}
		if !strings.Contains(vi, "BANDWIDTH=") || pmaAttr(vi, "RESOLUTION") != "128x72" {
			gate.release()
			t.Fatalf("single-variant variant line = %s, want BANDWIDTH and the probed RESOLUTION", vi)
		}
		if !strings.Contains(pv.uris[0], "rend0/index.m3u8?token="+token) {
			gate.release()
			t.Fatalf("master URI line = %q, want the tokenized rend0 media playlist", pv.uris[0])
		}
		// The variant playlist beneath it: partial (no ENDLIST) while the
		// tail is blocked — the master served from the FIRST byte.
		variantURL := pbPlaylistURI(pmaMediaPrefix+"pma_b/"+nonce+"/index.m3u8?token="+token, pv.uris[0])
		vStatus, vBody, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+variantURL, "", nil)
		if vStatus != http.StatusOK {
			gate.release()
			t.Fatalf("partial variant playlist: status %d, want 200", vStatus)
		}
		if strings.Contains(string(vBody), "#EXT-X-ENDLIST") {
			gate.release()
			t.Fatalf("partial variant playlist already carries ENDLIST:\n%s", vBody)
		}
		if !strings.Contains(string(vBody), "#EXT-X-MAP") {
			gate.release()
			t.Fatalf("partial variant playlist carries no init reference:\n%s", vBody)
		}

		// Release the tail; the same build completes and the master is
		// byte-identical — complete at birth, the merge never rewrites it.
		gate.release()
		pbAwaitStreams(t, w.st, "pma_b", "complete", 60*time.Second)
		pbAwaitIdle(t, qB, 30*time.Second)
		completeMaster := pmaGetMedia(t, w, pmaMediaPrefix+"pma_b/"+nonce+"/index.m3u8", token)
		if string(completeMaster) != string(partialMaster) {
			t.Fatalf("the master changed across the tail merge:\npartial:\n%s\ncomplete:\n%s",
				partialMaster, completeMaster)
		}
		vStatus, vBody, _ = pbDo(t, w.client, http.MethodGet, w.baseURL+variantURL, "", nil)
		if vStatus != http.StatusOK || !strings.Contains(string(vBody), "#EXT-X-ENDLIST") {
			t.Fatalf("complete variant playlist: status %d body:\n%s", vStatus, vBody)
		}
		if !strings.Contains(string(vBody), "#EXT-X-DISCONTINUITY") || !strings.Contains(string(vBody), "t/") {
			t.Fatalf("complete variant playlist missing the tail-merge markers:\n%s", vBody)
		}

		// The play URL is unchanged: the descriptor still names index.m3u8 —
		// now the master — under the same nonce.
		d := pmaDescriptor(t, baseURL, w, "pma_b")
		if d.Mode != "hls" || d.State != "complete" {
			t.Fatalf("pma_b descriptor = mode %q state %q, want hls/complete", d.Mode, d.State)
		}
		if !strings.HasPrefix(d.PlayURL, pmaMediaPrefix+"pma_b/"+nonce+"/index.m3u8?token=") {
			t.Fatalf("play URL = %q, want the unchanged index.m3u8 pointer at nonce %s", d.PlayURL, nonce)
		}
		served := pmaCodecsWire(t, d.Codecs)
		if len(served) != 2 || !strings.HasPrefix(served[0], "avc1.") || served[1] != "mp4a.40.2" {
			t.Fatalf("pma_b descriptor codecs = %v, want [avc1.*, mp4a.40.2]", served)
		}

		// The flow window: gate line, then the single-variant publish line.
		window := log.since(mark)
		gateLines := pmaFlowLines(window, "pack: gate")
		published := pmaFlowLines(window, "streams: pack published")
		if len(gateLines) != 1 || len(published) != 1 {
			t.Fatalf("pma_b flow = %d gate / %d published lines, want 1/1:\n%s",
				len(gateLines), len(published), strings.Join(window, "\n"))
		}
		for _, field := range []string{"item=pma_b", "nonce=" + nonce, "layout=single-variant",
			"variants=1", "audio=0", "codecs=recorded", "probes=1"} {
			if !strings.Contains(published[0], field) {
				t.Fatalf("published line %q lacks %q", published[0], field)
			}
		}
		joined := strings.Join(window, "\n")
		if strings.Contains(joined, "token=") || strings.Contains(joined, pmaMediaPrefix) {
			t.Fatalf("pack flow log carries token or play-URL material (INV4):\n%s", joined)
		}
	})

	// --- LEG (c): the finding-B read side -------------------------------------
	t.Run("c_matroska_legacy_read_side", func(t *testing.T) {
		pmaSeedItem(t, w, libID, "pma_c", "Movie C.mkv", mkvC, pmaMatroskaHEVCFacts(), "",
			map[string]any{"state": stream.StateNone})
		if err := enqueueMain("pma_c"); err != nil {
			t.Fatalf("enqueue pma_c: %v", err)
		}
		streams := pbAwaitStreams(t, w.st, "pma_c", "complete", 60*time.Second)
		pbAwaitIdle(t, qMain, 30*time.Second)
		nonce, _ := streams["nonce"].(string)
		if nonce == "" {
			t.Fatalf("pma_c persisted streams missing nonce: %v", streams)
		}

		// Rewind the namespace to a PRE-RECORD build: state complete with the
		// artifact pointer and nonce, NO codecs record, NO master marker —
		// exactly what the lane persisted before this change existed.
		row, err := w.st.GetItem(context.Background(), "pma_c")
		if err != nil {
			t.Fatalf("reload pma_c: %v", err)
		}
		doc := map[string]any{}
		if err := json.Unmarshal(row.Document, &doc); err != nil {
			t.Fatalf("decode pma_c doc: %v", err)
		}
		doc["streams"] = map[string]any{
			"state":    stream.StateComplete,
			"playlist": pmaMediaPrefix + "pma_c/" + nonce + "/index.m3u8",
			"nonce":    nonce,
		}
		raw, err := json.Marshal(doc)
		if err != nil {
			t.Fatalf("marshal pma_c doc: %v", err)
		}
		row.Document = raw
		if err := w.st.PutItem(context.Background(), row); err != nil {
			t.Fatalf("persist pre-record namespace: %v", err)
		}

		// The descriptor GET: the read side composes the finding-B shape.
		dMark := log.mark()
		d := pmaDescriptor(t, baseURL, w, "pma_c")
		if d.Mode != "hls" || d.State != "complete" {
			t.Fatalf("pma_c descriptor = mode %q state %q, want hls/complete (a pre-record build still plays)", d.Mode, d.State)
		}
		served := pmaCodecsWire(t, d.Codecs)
		if strings.Join(served, "|") != "hvc1.2.4.L120.B0|mp4a.40.2" {
			t.Fatalf("descriptor codecs = %v, want the finding-B composition [hvc1.2.4.L120.B0 mp4a.40.2] (deduped)", served)
		}
		lines := pmaFlowLines(log.since(dMark), "playback: descriptor")
		if len(lines) != 1 {
			t.Fatalf("captured %d decision lines for pma_c, want exactly ONE:\n%s",
				len(lines), strings.Join(log.since(dMark), "\n"))
		}
		for _, field := range []string{"item=pma_c", "mode=hls", "state=complete", "reason=packaged", "codecs_src=legacy"} {
			if !strings.Contains(lines[0], field) {
				t.Fatalf("decision line %q lacks %q", lines[0], field)
			}
		}
		// INV4 on the decision line: no token value, no play URL.
		if strings.Contains(lines[0], "token=") || strings.Contains(lines[0], pmaMediaPrefix) {
			t.Fatalf("decision line carries token or play-URL material (INV4): %s", lines[0])
		}
		// The legacy answer still serves the real build.
		token, _ := w.media.Issue("pma_c", time.Now())
		pmaGetMedia(t, w, d.PlayURL, token)
	})

	// --- LEG (e): the lazy repack-on-play --------------------------------------
	t.Run("e_lazy_repack_on_play", func(t *testing.T) {
		gateDir := t.TempDir()
		gate := pmaNewTailGate(t, gateDir, realFFmpeg)
		blocked := pmaBlockedService(w, filepath.Join(gateDir, "ffmpeg-block-tail.sh"))
		var packCalls int64
		qE := pmaQueue(t, w, blocked, func() { atomic.AddInt64(&packCalls, 1) })
		enqueueE := w.pbEnqueue(qE)
		playBase := pmaServer(t, w, enqueueE)

		pmaSeedItem(t, w, libID, "pma_e", "Movie E.mkv", mkvE, pmaH264Facts(), "",
			map[string]any{"state": stream.StateNone})
		// The hand-laid legacy build beside a namespace doc lacking the
		// version: complete + nonce, no master key (v0) — the stale signal.
		pmaHandLegacyBuild(t, w.media.Root, "pma_e", "legacy0")
		row, err := w.st.GetItem(context.Background(), "pma_e")
		if err != nil {
			t.Fatalf("reload pma_e: %v", err)
		}
		doc := map[string]any{}
		if err := json.Unmarshal(row.Document, &doc); err != nil {
			t.Fatalf("decode pma_e doc: %v", err)
		}
		doc["streams"] = map[string]any{
			"state":    stream.StateComplete,
			"playlist": pmaMediaPrefix + "pma_e/legacy0/index.m3u8",
			"nonce":    "legacy0",
		}
		raw, err := json.Marshal(doc)
		if err != nil {
			t.Fatalf("marshal pma_e doc: %v", err)
		}
		row.Document = raw
		if err := w.st.PutItem(context.Background(), row); err != nil {
			t.Fatalf("persist legacy namespace: %v", err)
		}

		// The first POST /play: exactly ONE repack enqueued (202).
		mark := log.mark()
		status, body, _ := pbDo(t, w.client, http.MethodPost, playBase+"/api/v1/items/pma_e/play", w.token, map[string]any{})
		if status != http.StatusAccepted {
			t.Fatalf("first play: status %d, want 202 (body=%s)", status, body)
		}
		var pr struct {
			Queued bool `json:"queued"`
		}
		if err := json.Unmarshal(body, &pr); err != nil || !pr.Queued {
			t.Fatalf("first play body = %s (decode %v), want queued:true", body, err)
		}
		queuedLines := pmaFlowLines(log.since(mark), "orchestrator: legacy repack queued")
		if len(queuedLines) != 1 || !strings.Contains(queuedLines[0], "item=pma_e") {
			t.Fatalf("captured %d legacy-repack-queued lines, want exactly ONE naming pma_e:\n%s",
				len(queuedLines), strings.Join(log.since(mark), "\n"))
		}

		// The repack is in flight (blocked at the tail): the OLD build keeps
		// serving — the descriptor still names legacy0 and its bytes answer.
		select {
		case <-gate.started:
		case <-time.After(60 * time.Second):
			gate.release()
			t.Fatalf("the repack never reached its tail; log:\n%s", strings.Join(log.since(mark), "\n"))
		}
		oldToken, _ := w.media.Issue("pma_e", time.Now())
		oldDesc := pmaDescriptor(t, playBase, w, "pma_e")
		if !strings.HasPrefix(oldDesc.PlayURL, pmaMediaPrefix+"pma_e/legacy0/index.m3u8?token=") {
			gate.release()
			t.Fatalf("descriptor during the repack = %q, want the legacy build still published", oldDesc.PlayURL)
		}
		oStatus, oldBody, _ := pbDo(t, w.client, http.MethodGet,
			playBase+pmaMediaPrefix+"pma_e/legacy0/index.m3u8?token="+oldToken, "", nil)
		if oStatus != http.StatusOK {
			gate.release()
			t.Fatalf("old build during the repack: status %d, want 200", oStatus)
		}
		if !strings.Contains(string(oldBody), "#EXT-X-ENDLIST") || strings.Contains(string(oldBody), "EXT-X-STREAM-INF") {
			gate.release()
			t.Fatalf("old build's served bytes are not the legacy media playlist:\n%s", oldBody)
		}
		if !strings.Contains(string(oldBody), "init.mp4?token="+oldToken) || !strings.Contains(string(oldBody), "seg-00000.m4s?token="+oldToken) {
			gate.release()
			t.Fatalf("old build's served playlist lost its tokenized refs:\n%s", oldBody)
		}

		// Release: the repack lands — fresh nonce, master marker, and the
		// composed master replacing the legacy layout.
		gate.release()
		streams := pmaAwaitFreshNonce(t, w.st, "pma_e", "legacy0", 60*time.Second)
		pbAwaitIdle(t, qE, 30*time.Second)
		freshNonce, _ := streams["nonce"].(string)
		if freshNonce == "" || freshNonce == "legacy0" {
			t.Fatalf("repack did not publish a fresh nonce: %v", streams)
		}
		if v, ok := streams["master"].(float64); !ok || v != float64(pack.MasterRuleVersion) {
			t.Fatalf("repacked namespace carries master %v, want the current rule version %d", streams["master"], pack.MasterRuleVersion)
		}
		dirs := pmaNonceDirs(t, w.media.Root, "pma_e")
		var haveFresh, haveLegacy bool
		for _, d := range dirs {
			switch d {
			case freshNonce:
				haveFresh = true
			case "legacy0":
				haveLegacy = true
			}
		}
		if !haveFresh || !haveLegacy {
			t.Fatalf("build dirs after the repack = %v, want the retention pair [%s (fresh) legacy0 (superseded)] both PRESENT — publish retains superseded builds", dirs, freshNonce)
		}
		newDesc := pmaDescriptor(t, playBase, w, "pma_e")
		if !strings.HasPrefix(newDesc.PlayURL, pmaMediaPrefix+"pma_e/"+freshNonce+"/index.m3u8?token=") {
			t.Fatalf("descriptor after the repack = %q, want the fresh nonce's playlist", newDesc.PlayURL)
		}
		freshToken, _ := w.media.Issue("pma_e", time.Now())
		freshMaster := pmaGetMedia(t, w, newDesc.PlayURL, freshToken)
		fv := pmaParseMaster(string(freshMaster))
		if len(fv.streamInf) != 1 || len(fv.uris) != 1 || len(fv.media) != 0 {
			t.Fatalf("repacked build root = %+v, want the composed single-variant master:\n%s", fv, freshMaster)
		}
		if got := pmaAttr(fv.streamInf[0], "CODECS"); !strings.HasPrefix(got, "avc1.") || !strings.Contains(got, "mp4a.40.2") {
			t.Fatalf("repacked master CODECS = %q, want the composed video+audio value", got)
		}
		if oldStatus, _, _ := pbDo(t, w.client, http.MethodGet,
			playBase+pmaMediaPrefix+"pma_e/legacy0/index.m3u8?token="+oldToken, "", nil); oldStatus != http.StatusOK {
			t.Fatalf("the superseded legacy build with the session's old token = status %d, want 200 — the retention contract keeps it on disk and serving", oldStatus)
		}
		// The flow's own line rode the job: exactly one gate + one publish.
		window := log.since(mark)
		if n := len(pmaFlowLines(window, "pack: gate")); n != 1 {
			t.Fatalf("repack flow logged %d gate lines, want 1:\n%s", n, strings.Join(window, "\n"))
		}
		pub := pmaFlowLines(window, "streams: pack published")
		if len(pub) != 1 {
			t.Fatalf("repack flow logged %d published lines, want 1:\n%s", len(pub), strings.Join(window, "\n"))
		}
		for _, field := range []string{"item=pma_e", "nonce=" + freshNonce, "layout=single-variant", "codecs=recorded"} {
			if !strings.Contains(pub[0], field) {
				t.Fatalf("repack published line %q lacks %q", pub[0], field)
			}
		}

		// The second POST /play: the current version closed the window —
		// NOTHING is enqueued (the negative, asserted against the queue/pack
		// observable, never a sleep).
		mark2 := log.mark()
		status, body, _ = pbDo(t, w.client, http.MethodPost, playBase+"/api/v1/items/pma_e/play", w.token, map[string]any{})
		if status != http.StatusOK {
			t.Fatalf("second play: status %d, want 200 (body=%s)", status, body)
		}
		if err := json.Unmarshal(body, &pr); err != nil || pr.Queued {
			t.Fatalf("second play body = %s (decode %v), want queued:false", body, err)
		}
		if lines := log.since(mark2); len(lines) != 0 {
			t.Fatalf("the second play logged anything at all — the current version did not close the decision:\n%s",
				strings.Join(lines, "\n"))
		}
		if got := atomic.LoadInt64(&packCalls); got != 1 {
			t.Fatalf("pack ran %d times after the second play, want exactly the ONE repack", got)
		}
		if s := qE.Stats(); s.Pending != 0 || s.InFlight != 0 {
			t.Fatalf("queue busy after the second play: %+v", s)
		}
		if after := gateStreams(t, w, "pma_e"); after["nonce"] != freshNonce {
			t.Fatalf("second play moved the build nonce %v -> %v", freshNonce, after["nonce"])
		}

		// The version-shape seeds (fix-tv-unblock-2 Interfaces 2, re-based on
		// the same predicate): a v1 boolean-true seed re-heals exactly ONCE
		// (its repacked namespace carries the current rule version); a
		// current-version seed never enqueues. pma_f rides qE — the tail gate
		// is already released, so its repack runs to completion.
		mkvF := filepath.Join(fixtures, "Movie F.mkv")
		pbMakeMKV(t, mkvF, 5*time.Second, false)
		pmaHandLegacyBuild(t, w.media.Root, "pma_f", "v1legacy")
		pmaSeedItem(t, w, libID, "pma_f", "Movie F.mkv", mkvF, pmaH264Facts(), "",
			map[string]any{
				"state":    stream.StateComplete,
				"playlist": pmaMediaPrefix + "pma_f/v1legacy/index.m3u8",
				"nonce":    "v1legacy",
				"master":   true, // the LEGACY v1 write — stale under v2
			})
		markF := log.mark()
		status, body, _ = pbDo(t, w.client, http.MethodPost, playBase+"/api/v1/items/pma_f/play", w.token, map[string]any{})
		if status != http.StatusAccepted {
			t.Fatalf("v1-seed play: status %d, want 202 (body=%s)", status, body)
		}
		if err := json.Unmarshal(body, &pr); err != nil || !pr.Queued {
			t.Fatalf("v1-seed play body = %s (decode %v), want queued:true", body, err)
		}
		queuedF := pmaFlowLines(log.since(markF), "orchestrator: legacy repack queued")
		if len(queuedF) != 1 || !strings.Contains(queuedF[0], "item=pma_f") {
			t.Fatalf("captured %d legacy-repack-queued lines for pma_f, want exactly ONE:\n%s",
				len(queuedF), strings.Join(log.since(markF), "\n"))
		}
		freshF := pmaAwaitFreshNonce(t, w.st, "pma_f", "v1legacy", 60*time.Second)
		pbAwaitIdle(t, qE, 30*time.Second)
		fNonce, _ := freshF["nonce"].(string)
		if fNonce == "" || fNonce == "v1legacy" {
			t.Fatalf("v1-seed repack did not publish a fresh nonce: %v", freshF)
		}
		if v, ok := freshF["master"].(float64); !ok || v != float64(pack.MasterRuleVersion) {
			t.Fatalf("repacked v1-seed namespace carries master %v, want the current rule version %d", freshF["master"], pack.MasterRuleVersion)
		}
		fDirs := pmaNonceDirs(t, w.media.Root, "pma_f")
		var haveFFresh, haveFLegacy bool
		for _, d := range fDirs {
			switch d {
			case fNonce:
				haveFFresh = true
			case "v1legacy":
				haveFLegacy = true
			}
		}
		if !haveFFresh || !haveFLegacy {
			t.Fatalf("pma_f build dirs after the repack = %v, want the retention pair [%s (fresh) v1legacy (superseded)] both PRESENT — publish retains superseded builds", fDirs, fNonce)
		}
		if got := atomic.LoadInt64(&packCalls); got != 2 {
			t.Fatalf("pack ran %d times after the v1-seed repack, want exactly 2 (pma_e's + pma_f's ONE repack)", got)
		}
		// The repacked v1 build is now current: a repeat play enqueues nothing.
		markF2 := log.mark()
		status, body, _ = pbDo(t, w.client, http.MethodPost, playBase+"/api/v1/items/pma_f/play", w.token, map[string]any{})
		if status != http.StatusOK {
			t.Fatalf("v1-seed second play: status %d, want 200 (body=%s)", status, body)
		}
		if err := json.Unmarshal(body, &pr); err != nil || pr.Queued {
			t.Fatalf("v1-seed second play body = %s (decode %v), want queued:false", body, err)
		}
		if lines := log.since(markF2); len(lines) != 0 {
			t.Fatalf("the repacked v1 build re-enqueued on its second play — the version did not close the window:\n%s",
				strings.Join(lines, "\n"))
		}

		// A current-version seed (master: 2, exactly what the success persist
		// writes) stays put: no enqueue, no line, no state change.
		pmaHandLegacyBuild(t, w.media.Root, "pma_g", "current0")
		pmaSeedItem(t, w, libID, "pma_g", "Movie G.mkv", mkvE, pmaH264Facts(), "",
			map[string]any{
				"state":    stream.StateComplete,
				"playlist": pmaMediaPrefix + "pma_g/current0/index.m3u8",
				"nonce":    "current0",
				"master":   pack.MasterRuleVersion,
			})
		markG := log.mark()
		status, body, _ = pbDo(t, w.client, http.MethodPost, playBase+"/api/v1/items/pma_g/play", w.token, map[string]any{})
		if status != http.StatusOK {
			t.Fatalf("current-seed play: status %d, want 200 (body=%s)", status, body)
		}
		if err := json.Unmarshal(body, &pr); err != nil || pr.Queued {
			t.Fatalf("current-seed play body = %s (decode %v), want queued:false", body, err)
		}
		if lines := log.since(markG); len(lines) != 0 {
			t.Fatalf("the current-version seed triggered anything at all:\n%s", strings.Join(lines, "\n"))
		}
		if got := atomic.LoadInt64(&packCalls); got != 2 {
			t.Fatalf("pack ran %d times after the current-seed play, want unchanged at 2", got)
		}
		if after := gateStreams(t, w, "pma_g"); after["nonce"] != "current0" {
			t.Fatalf("current-seed play moved the build nonce: %v", after["nonce"])
		}
	})
}
